"""Refresh rollback's SQLSTATE class names from the installed Python oracle.

Run: python rust/daemon/harness/rollback_error_classes.py
Only code-to-class data is copied; no Python runs in the native daemon.
"""
from pathlib import Path

from psycopg import errors


def generate() -> str:
    lines = [
        "// Generated by harness/rollback_error_classes.py from psycopg.errors.",
        "// A server SQLSTATE identifies its Python exception subclass; transport",
        "// failures have no SQLSTATE and are OperationalError.",
        "pub(super) fn class(code: Option<&str>) -> &'static str {",
        '    let Some(code) = code else {',
        '        return "OperationalError";',
        '    };',
        "    match code {",
    ]
    for code, cls in sorted(errors._sqlcodes.items()):
        if len(code) == 5 and code.isalnum():
            lines.append(f'        "{code}" => "{cls.__name__}",')
    lines += ['        _ => match code.get(..2).unwrap_or("") {']
    for code, cls in sorted(errors._base_exc_map.items()):
        if len(code) == 2:
            lines.append(f'            "{code}" => "{cls.__name__}",')
    lines += ['            _ => match code.get(..1).unwrap_or("") {']
    for code, cls in sorted(errors._base_exc_map.items()):
        if len(code) == 1:
            lines.append(f'                "{code}" => "{cls.__name__}",')
    lines += ['                _ => "DatabaseError",', "            },", "        },", "    }", "}"]
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    target = Path(__file__).resolve().parents[1] / "src/dream/rollback_pg_errors.rs"
    target.write_text(generate(), encoding="utf-8", newline="\n")
